fn copy(src: &[i32], s_start: usize, dest: &[i32], d_start: usize, len: usize) -> Vec<i32> {
    // Clone the entire destination array — elements outside [d_start, d_start+len)
    // are already correct and the result has the same length as dest.
    let mut result = dest.to_vec();

    // Overwrite the replacement range with the corresponding source subrange.
    for i in 0..len {
        result[d_start + i] = src[s_start + i];
    }

    result
}

